import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  h1Classes,
  h2Classes,
  h3Classes,
  h4Classes,
  blockquoteClasses,
  inlineCodeClasses,
  largeClasses,
  leadClasses,
  listClasses,
  mutedClasses,
  paragraphClasses,
  smallClasses,
  tableCellClasses,
  tableClasses,
  tableHeaderCellClasses,
  tableWrapperClasses,
} from "./view";

export {
  h1Classes,
  h2Classes,
  h3Classes,
  h4Classes,
  blockquoteClasses,
  inlineCodeClasses,
  largeClasses,
  leadClasses,
  listClasses,
  mutedClasses,
  paragraphClasses,
  smallClasses,
  tableCellClasses,
  tableClasses,
  tableHeaderCellClasses,
  tableWrapperClasses,
} from "./view";

const cn = (base: string, classes?: string): string =>
  [base, classes]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const h1 = <ParentMessage>(label: string, classes?: string): Html => {
  const h = html<ParentMessage>();
  return h.h1([h.Class(cn(h1Classes, classes))], [label]);
};

export const h2 = <ParentMessage>(label: string, classes?: string): Html => {
  const h = html<ParentMessage>();
  return h.h2([h.Class(cn(h2Classes, classes))], [label]);
};

export const h3 = <ParentMessage>(label: string, classes?: string): Html => {
  const h = html<ParentMessage>();
  return h.h3([h.Class(cn(h3Classes, classes))], [label]);
};

export const h4 = <ParentMessage>(label: string, classes?: string): Html => {
  const h = html<ParentMessage>();
  return h.h4([h.Class(cn(h4Classes, classes))], [label]);
};

export const p = <ParentMessage>(label: string, classes?: string): Html => {
  const h = html<ParentMessage>();
  return h.p([h.Class(cn(paragraphClasses, classes))], [label]);
};

export const blockquote = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.blockquote(
    [h.Class(cn(blockquoteClasses, classes))],
    [label]
  );
};

export const table = <ParentMessage>(
  headers: readonly string[],
  rows: readonly (readonly string[])[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [h.Class(cn(tableWrapperClasses, classes))],
    [
      h.table(
        [h.Class(tableClasses)],
        [
          h.thead(
            [],
            [
              h.tr(
                [],
                headers.map((header) =>
                  h.th([h.Class(tableHeaderCellClasses)], [header])
                )
              ),
            ]
          ),
          h.tbody(
            [],
            rows.map((row) =>
              h.tr(
                [],
                row.map((cell) => h.td([h.Class(tableCellClasses)], [cell]))
              )
            )
          ),
        ]
      ),
    ]
  );
};

export const lead = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.p([h.Class(cn(leadClasses, classes))], [label]);
};

export const large = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div([h.Class(cn(largeClasses, classes))], [label]);
};

export const small = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.small([h.Class(cn(smallClasses, classes))], [label]);
};

export const muted = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.p([h.Class(cn(mutedClasses, classes))], [label]);
};

export const inlineCode = <ParentMessage>(
  label: string,
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.code([h.Class(cn(inlineCodeClasses, classes))], [label]);
};

export const ul = <ParentMessage>(
  items: readonly string[],
  classes?: string
): Html => {
  const h = html<ParentMessage>();
  return h.ul(
    [h.Class(cn(listClasses, classes))],
    items.map((item) => h.li([], [item]))
  );
};

export const h1Classes =
  "scroll-m-20 text-4xl font-extrabold tracking-normal text-gray-950";

export const h2Classes =
  "scroll-m-20 border-b border-gray-200 pb-2 text-3xl font-semibold tracking-normal text-gray-950";

export const h3Classes =
  "scroll-m-20 text-2xl font-semibold tracking-normal text-gray-950";

export const h4Classes =
  "scroll-m-20 text-xl font-semibold tracking-normal text-gray-950";

export const paragraphClasses = "leading-7 text-gray-700";

export const blockquoteClasses =
  "mt-6 border-l-2 border-gray-200 pl-6 italic text-gray-700";

export const tableWrapperClasses = "my-6 w-full overflow-y-auto";

export const tableClasses = "w-full text-sm";

export const tableHeaderCellClasses =
  "border-b border-gray-200 px-4 py-2 text-left font-bold text-gray-950";

export const tableCellClasses = "border-b border-gray-200 px-4 py-2";

export const leadClasses = "text-xl text-gray-500";

export const largeClasses = "text-lg font-semibold text-gray-950";

export const smallClasses = "text-sm leading-none font-medium text-gray-950";

export const mutedClasses = "text-sm text-gray-500";

export const inlineCodeClasses =
  "relative rounded bg-gray-100 px-1.5 py-0.5 font-mono text-sm font-semibold text-gray-900";

export const listClasses = "my-6 ml-6 list-disc [&>li]:mt-2";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Typography from "./index";

const view = (): Html => {
  const h = html<never>();

  return h.div(
    [],
        [
          Typography.h1("Component registry"),
          Typography.h2("Principles"),
          Typography.h3("Details"),
          Typography.h4("Fine print"),
          Typography.p("Reusable text helpers."),
          Typography.blockquote("A useful quotation."),
          Typography.table(["Name", "Value"], [["Status", "Ready"]]),
          Typography.inlineCode("classes"),
          Typography.lead("Lead copy."),
          Typography.large("Large copy."),
          Typography.small("Small copy."),
          Typography.muted("Muted copy."),
        ]
      );
};

describe("Typography registry view", () => {
  test("renders the documented static surface", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Component registry")).toExist(),
      Scene.expect(Scene.text("Principles")).toExist(),
      Scene.expect(Scene.text("Fine print")).toExist(),
      Scene.expect(Scene.text("Status")).toExist(),
      Scene.expect(Scene.text("Muted copy.")).toExist()
    );
  });
});
